const catalog = {
  T1: "The user should be able to filter reports by date range, category, and status. Results must load in under 2 seconds. PM: Sarah. Deadline: Q3.",
  Transcript1: "Meeting: Product Planning - Reporting Dashboard
Date: March 15, 2026
Attendees: Sarah (PM), Raj (Engineering Lead), Lisa (Design)

Sarah: Okay let's talk about the reporting feature. Users have been asking for this for months. The key requirement is that users should be able to filter reports by date range, category, and status.

Raj: Makes sense. What about performance? If they're pulling large datasets we need to think about load times.

Sarah: Good point. Results must load in under 2 seconds. That's a hard requirement from the enterprise customers.

Lisa: Are we doing this as a new page or adding it to the existing dashboard?

Sarah: New dedicated page. But it should match our existing design system.

Raj: Who owns this? And what's the timeline?

Sarah: I'm the PM owner. Deadline is end of Q3. Raj, your team would handle the backend. Lisa, we'd need designs by end of April.

Raj: We'll need to decide on the data source. Are we querying live or using a pre-computed data warehouse?

Sarah: TBD on that. Let's decide after we see Lisa's designs and understand the query patterns.",
};
const testId = String($json.testId || 'T1').trim();
if (!catalog[testId]) {
  throw new Error('Unknown testId "' + testId + '". Use T1 or Transcript1.');
}
return [{
  json: {
    testId,
    chatInput: catalog[testId],
    startTime: new Date().toISOString(),
  },
}];

const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  const v = c === 'x' ? r : ((r & 0x3) | 0x8);
  return v.toString(16);
});

const src = $('Resolve Input').first().json;
const out = $input.first().json;
const outputText =
  typeof out.text === 'string' ? out.text :
  typeof out.output === 'string' ? out.output :
  JSON.stringify(out);

const traceId = uuid();
const startTime = src.startTime || new Date().toISOString();
const endTime = new Date().toISOString();
const testId = src.testId || 'unspecified';

const batch = [
  {
    id: uuid(),
    type: 'trace-create',
    timestamp: endTime,
    body: {
      id: traceId,
      name: 'prd-genie-slice1',
      input: src.chatInput,
      output: outputText,
      tags: ['prd-genie', 'slice1', testId],
      metadata: { testId, release: 'R1', platform: 'n8n-ik-cloud' },
    },
  },
  {
    id: uuid(),
    type: 'generation-create',
    timestamp: endTime,
    body: {
      id: uuid(),
      traceId,
      name: 'Requirement Extractor',
      model: 'gpt-4o',
      startTime,
      endTime,
      input: src.chatInput,
      output: outputText,
      metadata: { testId, agent: 'Requirement Extractor' },
    },
  },
];

return [{ json: { batch, traceId, testId, extractorOutput: outputText } }];
